-- New runtime only. Existing research remains archived, never deleted.
create schema if not exists extensions;
create extension if not exists pgcrypto with schema extensions;
do $$ begin
 if exists(select 1 from pg_namespace where nspname='lab') then
  if exists(select 1 from pg_namespace where nspname='lab_legacy_v2') then raise exception 'LEGACY_SCHEMA_EXISTS'; end if;
  alter schema lab rename to lab_legacy_v2;
  revoke all on schema lab_legacy_v2 from public,anon,authenticated;
 end if;
 if exists(select 1 from pg_namespace where nspname='lab_private') then
  alter schema lab_private rename to lab_private_legacy_v2;
  revoke all on schema lab_private_legacy_v2 from public,anon,authenticated;
 end if;
end $$;
create schema lab;
create schema lab_private;
revoke all on schema lab,lab_private from public,anon,authenticated;
grant usage on schema lab,lab_private to service_role;
alter default privileges in schema lab revoke all on tables from public,anon,authenticated;
alter default privileges in schema lab_private revoke all on tables from public,anon,authenticated;
create table lab.workspaces(id uuid primary key default gen_random_uuid(),name text not null,active boolean not null default false,restored_from uuid,created_at timestamptz not null default now(),settings jsonb not null default '{"api_enabled":false,"scheduler_enabled":false}');
create unique index one_active_workspace on lab.workspaces(active) where active;
create table lab.members(id uuid not null,workspace_id uuid not null references lab.workspaces,id_email text not null,role text not null check(role in('admin','researcher')),active boolean not null default true,primary key(workspace_id,id),unique(workspace_id,id_email));
create table lab_private.email_allowlist(workspace_id uuid not null references lab.workspaces,email text not null,role text not null check(role in('admin','researcher')),active boolean not null default true,primary key(workspace_id,email));
create table lab.papers(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,created_by uuid not null,title text not null,metadata jsonb not null default '{}',archived boolean not null default false,created_at timestamptz not null default now(),unique(workspace_id,id));
create table lab.assets(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,paper_id uuid,kind text not null check(kind in('source','prepared','raw','archives')),path text not null unique,bytes bigint not null check(bytes>=0),sha256 text not null check(sha256~'^[a-f0-9]{64}$'),status text not null default 'reserved' check(status in('reserved','verified','failed')),server_hash boolean not null default false,metadata jsonb not null default '{}',created_by uuid not null,created_at timestamptz not null default now(),unique(workspace_id,id),foreign key(workspace_id,paper_id) references lab.papers(workspace_id,id),check((kind='source' and bytes>0 and bytes<=41943040) or (kind='prepared' and bytes>0 and bytes<=8388608) or (kind='raw' and bytes<=1048576) or (kind='archives' and bytes<=16777216)));
create table lab.checkpoints(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,paper_id uuid not null,title text not null,created_by uuid not null,created_at timestamptz not null default now(),unique(workspace_id,id),foreign key(workspace_id,paper_id) references lab.papers(workspace_id,id));
create table lab.checkpoint_revisions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,checkpoint_id uuid not null,version_no integer not null check(version_no>0),edit_version integer not null default 1,status text not null default 'draft' check(status in('draft','preparing','review','approved')),body jsonb not null,input_hash text,reference_hash text,approved_by uuid,approved_at timestamptz,created_by uuid not null,created_at timestamptz not null default now(),unique(workspace_id,id),unique(checkpoint_id,version_no),foreign key(workspace_id,checkpoint_id) references lab.checkpoints(workspace_id,id));
create table lab.revision_assets(workspace_id uuid not null,revision_id uuid not null,asset_id uuid not null,primary key(revision_id,asset_id),foreign key(workspace_id,revision_id) references lab.checkpoint_revisions(workspace_id,id),foreign key(workspace_id,asset_id) references lab.assets(workspace_id,id));
create table lab.protocol_versions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,body jsonb not null,sha256 text not null,created_at timestamptz not null default now(),unique(workspace_id,id));
create table lab.model_profiles(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,provider text not null check(provider in('google','openai','anthropic')),model_id text not null,api_family text not null,parameters jsonb not null default '{}',output_cap integer not null check(output_cap between 256 and 32768),pricing jsonb not null default '{}',capabilities jsonb not null default '{}',enabled boolean not null default false,created_at timestamptz not null default now(),unique(workspace_id,id));
create table lab.plans(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,created_by uuid not null,name text not null,k integer not null check(k between 1 and 10),repeats integer not null check(repeats between 1 and 10),cohort text not null check(cohort in('pilot','main','fixture')),transport text not null check(transport in('api','manual_web','mock')),status text not null default 'paused' check(status in('paused','running','cancelled','complete')),scheduled_at timestamptz not null default now(),protocol jsonb not null,condition_hash text not null,created_at timestamptz not null default now(),unique(workspace_id,id),check((transport='mock')=(cohort='fixture')));
create table lab.plan_inputs(workspace_id uuid not null,plan_id uuid not null,revision_id uuid not null,paper_id uuid not null,checkpoint_id uuid not null,snapshot jsonb not null,input_hash text not null,reference_hash text not null,primary key(plan_id,revision_id),foreign key(workspace_id,plan_id) references lab.plans(workspace_id,id),foreign key(workspace_id,revision_id) references lab.checkpoint_revisions(workspace_id,id));
create table lab.plan_models(workspace_id uuid not null,plan_id uuid not null,provider text not null check(provider in('google','openai','anthropic')),snapshot jsonb not null,primary key(plan_id,provider),foreign key(workspace_id,plan_id) references lab.plans(workspace_id,id));
create table lab.runs(id uuid primary key default gen_random_uuid(),original_id uuid,workspace_id uuid not null,plan_id uuid not null,revision_id uuid not null,generator text not null check(generator in('google','openai','anthropic')),repeat_index integer not null check(repeat_index between 1 and 10),created_at timestamptz not null default now(),unique(workspace_id,id),unique(plan_id,revision_id,generator,repeat_index),foreign key(workspace_id,plan_id) references lab.plans(workspace_id,id),foreign key(plan_id,revision_id) references lab.plan_inputs(plan_id,revision_id));
create table lab.jobs(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,run_id uuid not null,plan_id uuid not null,stage text not null check(stage in('generate','select','usefulness','agreement')),provider text not null check(provider in('google','openai','anthropic')),depends_on uuid,status text not null default 'queued' check(status in('queued','running','complete','parse_failed','blocked','unknown_remote','failed','cancelled')),due_at timestamptz not null default now(),lease_until timestamptz,attempt_no integer not null default 0,last_error text,created_at timestamptz not null default now(),unique(workspace_id,id),unique(run_id,stage,provider),foreign key(workspace_id,run_id) references lab.runs(workspace_id,id),foreign key(workspace_id,plan_id) references lab.plans(workspace_id,id),foreign key(workspace_id,depends_on) references lab.jobs(workspace_id,id));
create index jobs_claim on lab.jobs(provider,due_at,created_at) where status='queued';
create table lab.attempts(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,job_id uuid not null,attempt_no integer not null,milestone text not null default 'claimed',request_snapshot jsonb,request_asset_id uuid,response_asset_id uuid,response_hash text,parsed jsonb,metadata jsonb not null default '{}',send_started_at timestamptz,response_stored_at timestamptz,completed_at timestamptz,created_at timestamptz not null default now(),unique(workspace_id,id),unique(job_id,attempt_no),foreign key(workspace_id,job_id) references lab.jobs(workspace_id,id),foreign key(workspace_id,request_asset_id) references lab.assets(workspace_id,id),foreign key(workspace_id,response_asset_id) references lab.assets(workspace_id,id));
create table lab.ideas(id uuid primary key default gen_random_uuid(),original_id uuid,workspace_id uuid not null,run_id uuid not null,candidate_id text not null check(candidate_id~'^I([1-9]|10)$'),body jsonb not null,anonymization_diff jsonb,unique(workspace_id,id),unique(run_id,candidate_id),foreign key(workspace_id,run_id) references lab.runs(workspace_id,id));
create table lab.selections(workspace_id uuid not null,run_id uuid primary key,candidate_id text not null,body jsonb not null,attempt_id uuid not null,foreign key(run_id,candidate_id) references lab.ideas(run_id,candidate_id),foreign key(workspace_id,attempt_id) references lab.attempts(workspace_id,id));
create table lab.usefulness_ratings(workspace_id uuid not null,run_id uuid not null,candidate_id text not null,judge text not null,score integer check(score between 0 and 4),body jsonb not null,attempt_id uuid not null,primary key(run_id,candidate_id,judge),foreign key(run_id,candidate_id) references lab.ideas(run_id,candidate_id),foreign key(workspace_id,attempt_id) references lab.attempts(workspace_id,id));
create table lab.agreement_ratings(workspace_id uuid not null,run_id uuid not null,candidate_id text not null,judge text not null,label text not null check(label in('none','partial','core','undetermined')),body jsonb not null,attempt_id uuid not null,primary key(run_id,candidate_id,judge),foreign key(run_id,candidate_id) references lab.ideas(run_id,candidate_id),foreign key(workspace_id,attempt_id) references lab.attempts(workspace_id,id));
create table lab.review_samples(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,seed text not null default '20261023',manifest jsonb not null,created_at timestamptz not null default now(),unique(workspace_id,id));
create table lab.review_assignments(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,sample_id uuid not null,idea_id uuid not null,reviewer_id uuid not null,stratum text not null,unique(workspace_id,id),unique(sample_id,idea_id,reviewer_id),foreign key(workspace_id,sample_id) references lab.review_samples(workspace_id,id),foreign key(workspace_id,idea_id) references lab.ideas(workspace_id,id),foreign key(workspace_id,reviewer_id) references lab.members(workspace_id,id));
create table lab.review_revisions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,assignment_id uuid not null,phase text not null check(phase in('usefulness','agreement')),version_no integer not null default 1,body jsonb not null,created_by uuid not null,created_at timestamptz not null default now(),unique(assignment_id,phase,version_no),foreign key(workspace_id,assignment_id) references lab.review_assignments(workspace_id,id));
create table lab.analysis_snapshots(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,filters jsonb not null,body jsonb not null,sha256 text not null,created_by uuid not null,created_at timestamptz not null default now(),unique(workspace_id,id));
create table lab.export_manifests(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,analysis_id uuid not null,body jsonb not null,created_by uuid not null,created_at timestamptz not null default now(),foreign key(workspace_id,analysis_id) references lab.analysis_snapshots(workspace_id,id));
create table lab.backup_manifests(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,body jsonb not null,status text not null default 'preparing' check(status in('preparing','downloaded')),created_by uuid not null,created_at timestamptz not null default now(),downloaded_at timestamptz);
create table lab.restore_sessions(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,target_workspace_id uuid not null references lab.workspaces,manifest jsonb not null,id_map jsonb not null default '{}',progress jsonb not null default '{}',reserved_bytes bigint not null,status text not null default 'importing' check(status in('importing','verified','active','failed')),created_by uuid not null,created_at timestamptz not null default now());
create table lab.audit_events(id uuid primary key default gen_random_uuid(),workspace_id uuid not null references lab.workspaces,actor uuid,action text not null,resource_id uuid,body jsonb not null default '{}',created_at timestamptz not null default now());
create index jobs_by_plan on lab.jobs(plan_id);
create table lab_private.plan_fairness(plan_id uuid primary key references lab.plans,last_claimed_at timestamptz not null default now());
create table lab_private.provider_secrets(workspace_id uuid not null references lab.workspaces,provider text not null,encrypted jsonb not null,last_four text not null,key_version integer not null,primary key(workspace_id,provider));
create table lab_private.provider_runtime(provider text primary key check(provider in('google','openai','anthropic')),paused boolean not null default false,blocked_reason text,rpm integer not null default 5,tpm integer not null default 100000,min_interval_ms integer not null default 15000,last_claim timestamptz,last_plan uuid,last_success timestamptz,next_allowed_at timestamptz);
insert into lab_private.provider_runtime(provider) values('google'),('openai'),('anthropic');
create table lab_private.quota_reservations(id uuid primary key default gen_random_uuid(),provider text not null references lab_private.provider_runtime,job_id uuid not null,attempt_id uuid not null,estimated_tokens bigint not null,reserved_usd numeric not null default 0,reserved_storage_bytes bigint not null default 0,actual_tokens bigint,actual_usd numeric,status text not null default 'held' check(status in('held','settled','released','unknown')),created_at timestamptz not null default now(),unique(attempt_id));
create table lab_private.usage_budgets(workspace_id uuid not null references lab.workspaces,provider text not null,enabled boolean not null default false,budget_usd numeric not null default 0 check(budget_usd>=0),spent_usd numeric not null default 0,reserved_usd numeric not null default 0,org_verified_at timestamptz,primary key(workspace_id,provider));
create table lab_private.provider_files(id uuid primary key default gen_random_uuid(),workspace_id uuid not null,provider text not null,asset_id uuid not null,sha256 text not null,remote_id text not null,state text not null,expires_at timestamptz,last_verified_at timestamptz,created_at timestamptz not null default now(),unique(workspace_id,provider,asset_id));
create table lab_private.idempotency_requests(workspace_id uuid not null,actor uuid not null,key text not null,payload_hash text not null,result jsonb not null,created_at timestamptz not null default now(),primary key(workspace_id,actor,key));
create table lab_private.internal_nonces(nonce uuid primary key,created_at timestamptz not null default now());
create table lab_private.dispatch_outbox(id uuid primary key default gen_random_uuid(),job_id uuid,created_at timestamptz not null default now(),delivered_at timestamptz);
create table lab_private.scheduler_state(id boolean primary key default true check(id),enabled boolean not null default false,last_tick timestamptz,last_dispatch timestamptz,egress_bytes bigint not null default 0,edge_calls bigint not null default 0,month text not null default to_char(now(),'YYYY-MM'));
insert into lab_private.scheduler_state(id) values(true);
create table lab_private.restore_rows(session_id uuid not null references lab.restore_sessions,section text not null,row_index integer not null,row_hash text not null,primary key(session_id,section,row_index));
create table lab_private.restore_files(session_id uuid not null references lab.restore_sessions,asset_id uuid not null,sha256 text not null,checked boolean not null default false,primary key(session_id,asset_id));
create function lab_private.hash(v jsonb) returns text language sql immutable security invoker set search_path='' as $$ select encode(extensions.digest(v::text,'sha256'),'hex') $$;
create function lab_private.actor(w uuid,a uuid,admin_only boolean default false) returns lab.members language plpgsql security invoker set search_path='' as $$ declare m lab.members;begin select * into m from lab.members where workspace_id=w and id=a and active;if not found or(admin_only and m.role<>'admin') then raise exception 'FORBIDDEN';end if;return m;end $$;
create function lab_private.immutable() returns trigger language plpgsql security invoker set search_path='' as $$ begin raise exception 'IMMUTABLE_RECORD';end $$;
create function lab_private.revision_guard() returns trigger language plpgsql security invoker set search_path='' as $$ begin if old.status='approved' then raise exception 'IMMUTABLE_APPROVED_REVISION';end if;new.edit_version=old.edit_version+1;return new;end $$;
create trigger revision_guard before update on lab.checkpoint_revisions for each row execute function lab_private.revision_guard();
create trigger revision_delete before delete on lab.checkpoint_revisions for each row when(old.status='approved') execute function lab_private.immutable();
do $$ declare t text;begin
 foreach t in array array['plan_inputs','plan_models','protocol_versions','ideas','selections','usefulness_ratings','agreement_ratings','review_revisions','analysis_snapshots'] loop execute format('create trigger immutable before update or delete on lab.%I for each row execute function lab_private.immutable()',t);end loop;
 for t in select tablename from pg_tables where schemaname in('lab','lab_private') loop null;end loop;
end $$;
do $$ declare r record;begin for r in select schemaname,tablename from pg_tables where schemaname in('lab','lab_private') loop execute format('alter table %I.%I enable row level security',r.schemaname,r.tablename);execute format('revoke all on %I.%I from public,anon,authenticated',r.schemaname,r.tablename);execute format('grant select,insert,update,delete on %I.%I to service_role',r.schemaname,r.tablename);end loop;end $$;
revoke execute on all functions in schema lab_private from public,anon,authenticated;
grant execute on all functions in schema lab_private to service_role;
insert into storage.buckets(id,name,public,file_size_limit) values('source','source',false,41943040),('prepared','prepared',false,8388608),('raw','raw',false,1048576),('archives','archives',false,16777216) on conflict(id) do update set public=false,file_size_limit=excluded.file_size_limit;
